#!/usr/bin/env python3
import hashlib, importlib.util, json, pathlib, subprocess, urllib.request
ROOT=pathlib.Path(__file__).resolve().parents[1];E=ROOT/'docs/research/museum-image-recovery-20261013/batches/000013'
spec=importlib.util.spec_from_file_location('b',ROOT/'ops/museum-image-recovery-batch-000013.py');b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
def sha(x): return hashlib.sha256(x).hexdigest()
def main():
 checked=json.loads((E/'checked-artworks.json').read_text());ids=[x['artwork_id'] for x in checked];priorids=[]
 for p in sorted(E.parent.glob('0000*/checked-artworks.json')):
  if p.parent.name!='000013':priorids += [x['artwork_id'] for x in json.loads(p.read_text())]
 rows=json.loads(b.sql("SELECT json_agg(jsonb_build_object('id',a.id,'primary_media_id',a.primary_media_id,'status',a.status,'path',m.storage_path,'checksum',m.checksum_sha256,'bytes',m.byte_size,'rights',m.rights_status,'links',(SELECT count(*) FROM artwork_media am WHERE am.artwork_id=a.id),'evidence',(SELECT count(*) FROM media_rights_evidence re WHERE re.media_id=a.primary_media_id)) ORDER BY a.id) FROM artworks a LEFT JOIN media_assets m ON m.id=a.primary_media_id WHERE a.id IN ("+','.join(b.lit(x) for x in ids)+")"))
 delivered=[x for x in rows if x['primary_media_id']];assert len(delivered)==1 and sum(x['primary_media_id'] is None for x in rows)==9
 plan=json.loads((E/'delivery-plan.json').read_text())[0];assert delivered[0]['checksum']==plan['derivative_sha256'] and delivered[0]['bytes']<=100000 and delivered[0]['links']==1 and delivered[0]['evidence']==1
 public_url='https://artlines.org'+plan['derivative_path'];raw=urllib.request.urlopen(public_url,timeout=30).read();assert sha(raw)==plan['derivative_sha256']
 storage=json.loads(subprocess.check_output(['gcloud','storage','objects','describe','gs://artline-508319-images'+plan['derivative_path'],'--project=artline-508319','--account=vadim@alingva.com','--format=json'],text=True));assert int(storage['size'])==plan['derivative_bytes']
 out={'verified_at':b.now(),'checked_artworks_json_valid':True,'distinct_checked_ids':len(set(ids)),'prior_campaign_overlap':len(set(ids)&set(priorids)),'campaign_total_ids':len(priorids)+len(ids),'campaign_distinct_ids':len(set(priorids+ids)),'production_rows_read_back':len(rows),'newly_illustrated':1,'held_without_image':9,'source':{'official_api_records_checked':10,'exact_native_accession_title_matches':10,'copyrighted_records':9,'cc0_records':1,'official_image_routes':1,'access_holds':0},'database':{'primary_media_ids':[delivered[0]['primary_media_id']],'media_checksums_match':True,'artwork_media_links':1,'rights_evidence_rows':1,'still_imageless_others':9,'editorial_statuses_preserved':True},'storage':[{'artwork_id':plan['artwork_id'],'bucket':'artline-508319-images','generation':storage['generation'],'bytes':int(storage['size']),'public_sha256':sha(raw)}],'public':{'asset_http_200':True,'asset_checksums_match':True,'url':public_url},'visual':{'original_reviewed':True,'derivative_reviewed':True,'full_frame':True,'proportions_preserved':True,'all_derivatives_at_most_100000_bytes':True},'programmes_unchanged':True,'local_catalogue_connections':0,'batch107_reconciled_before_selection':True,'limitations':['Nine exact Cleveland records are marked Copyrighted and expose no official image route; no image was inferred from discovery thumbnails or unrelated versions.']}
 assert out['prior_campaign_overlap']==0 and out['campaign_distinct_ids']==130;b.save('independent-verification.json',out);print(json.dumps(out))
if __name__=='__main__':main()
